INSERT INTO offre (id,titre,poste,nombre_postes,diplome_requis,experience_min,specialite,langues,missions,competences,mots_cles,date_limite,actif,date_creation) VALUES (1,'(01) Chef de projets Architecte','(01) Chef de projets Architecte',1,'Architecte (Diplôme d’état Marocain ou diplôme privé reconnu par l’Etat ou diplôme étranger',1,'','','o Pilote, coordonne et contrôle la réalisation des projets lancés par l’ADER-FES, dans le respect des
spécifications, des engagements contractuels et dans le respect des orientations de l’ADER-FES ;
o Vérifie la conformité des études architecturales et techniques avec les termes de référence ;
o Assure la maîtrise d’ouvrage des projets et l’interface avec les équipes projets internes ou externe ;
o Rédige des comptes rendus sur l’avancement des travaux.','Techniques :
o Maîtrise du marché de réhabilitation d’aménagement et des techniques de construction ;
o Maîtrise de la réglementation du domaine ;
o Maîtrise des études techniques et urbanistiques ;
o Maîtrise des démarches auprès des différentes administrations pour mener efficacement les projets ;
o Maîtrise de l’exécution des différents travaux par les entreprises et leur suivi.
Comportementales et Managériales :
o Capacité à manager des projets ;
o Capacité à coopérer avec les collègues de son équipe en vue d''atteindre les objectifs communs ;
o Capacité à identifier à son poste de travail des problèmes simples et /ou récurrents et à appliquer les
procédures existantes pour les résoudre.',NULL,'11Décembre 2024',TRUE,'2026-07-29 15:52:27.261629') ON CONFLICT (id) DO NOTHING;
INSERT INTO offre (id,titre,poste,nombre_postes,diplome_requis,experience_min,specialite,langues,missions,competences,mots_cles,date_limite,actif,date_creation) VALUES (2,'(02) Charge de Communication et Marketing Digital','(02) Charge de Communication et Marketing Digital',2,'',0,'','Arabe, Français, Anglais','o Elaborer et mettre en oeuvre la strategie de communication de l''ADER-FES ;
o Gerer les reseaux sociaux et le site web institutionnel de l''agence ;
o Produire des contenus digitaux (articles, videos, infographies) ;
o Assurer la couverture mediatique des evenements organises par l''agence ;
o Concevoir les supports de communication (plaquettes, affiches, newsletters) ;
o Suivre et analyser les indicateurs de performance des campagnes digitales.
Principales Attributions :
o Rediger et diffuser les communiques de presse et actualites de l''agence ;
o Coordonner avec les partenaires medias et institutionnels ;
o Organiser les conferences de presse et evenements de l''agence ;
o Assurer la veille concurrentielle et mediatique ;
o Gerer le budget communication en coordination avec la direction financiere.','',NULL,'',TRUE,'2026-07-29 16:24:53.072371') ON CONFLICT (id) DO NOTHING;
