INSERT INTO offre (id,titre,poste,nombre_postes,diplome_requis,experience_min,specialite,langues,missions,competences,mots_cles,date_limite,actif,date_creation) VALUES (4,'(04) Assistant(e) Architecte','Assistant Architecte',1,'Licence en Architecture ou Technicien Spécialisé en Bâtiment/Dessin',1,'Architecture','Arabe, Français','Assister l''architecte responsable dans le suivi des projets d''amenagement et de rehabilitation ; Preparer et mettre a jour les plans et documents techniques (AutoCAD) ; Participer aux visites de chantier et rediger les comptes rendus de suivi ; Assurer le classement et l''archivage des dossiers techniques des projets ; Appuyer la coordination avec les entreprises et bureaux d''etudes intervenants.','Techniques :
o Maitrise du logiciel AutoCAD et des outils de dessin technique ;
o Connaissance des normes de construction et d''amenagement urbain ;
o Capacite a lire et interpreter des plans architecturaux ;
o Notions de suivi de chantier et de controle qualite.
Comportementales :
o Rigueur et sens de l''organisation dans le classement des dossiers ;
o Capacite a travailler en equipe avec les architectes et ingenieurs ;
o Bon relationnel avec les entreprises et prestataires.',NULL,'30/09/2026',TRUE,'2026-08-24 14:14:03.212742') ON CONFLICT (id) DO NOTHING;
